INSERT INTO destinations (slug, name, category_id, region, summary, description, history, latitude, longitude, coords_verified, difficulty, visit_duration, season, access_info, safety_info, status, is_featured, sources) VALUES ('cascada-arenal', 'Cascada Arenal', (SELECT id FROM destination_categories WHERE key='cascadas'), 'Arenal, Río Congo Arriba · Chepigana', 'Cascada escalonada en roca, rodeada de selva, con pozas para refrescarse.', 'Una de las cascadas emblemáticas de Darién y escenario de las jornadas Explora & Reforesta. El agua cae en varios escalones de roca hasta pozas cristalinas en medio de la selva del valle de Arenal.', 'Desde 2022 la comunidad y @xplore_darien organizan aquí jornadas de reforestación con más de 1 500 plantas por edición.', 8.612, -78.247, false, 'moderada', 'Día completo', 'Todo el año; más caudal en temporada lluviosa (may–nov)', 'Por la Panamericana hasta Río Congo Arriba y caminata guiada.', 'Roca resbaladiza. No subir a la cascada con crecidas. Ir siempre con guía local.', 'published', true, ARRAY['https://www.instagram.com/p/CWtgRN1vXPq/','https://www.instagram.com/p/DfgX-g1Dq5f/','https://www.instagram.com/p/CfWv0KUuh_m/']::text[]) ON CONFLICT (slug) DO NOTHING;
