INSERT INTO translations (entity_type, entity_id, locale, field, value) SELECT 'destination', id::text, 'en', 'summary', 'Tiered rock waterfall in the rainforest with natural pools.' FROM destinations WHERE slug='cascada-arenal' ON CONFLICT (entity_type, entity_id, locale, field) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO translations (entity_type, entity_id, locale, field, value) SELECT 'destination', id::text, 'en', 'description', 'One of Darién''s signature waterfalls and home of the Explora & Reforesta days. Water drops over several rock steps into clear pools in the Arenal valley forest.' FROM destinations WHERE slug='cascada-arenal' ON CONFLICT (entity_type, entity_id, locale, field) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO translations (entity_type, entity_id, locale, field, value) SELECT 'destination', id::text, 'en', 'history', 'Since 2022 the community and @xplore_darien have run reforestation days here, planting 1,500+ trees per edition.' FROM destinations WHERE slug='cascada-arenal' ON CONFLICT (entity_type, entity_id, locale, field) DO UPDATE SET value = EXCLUDED.value;
