INSERT INTO destinations (slug, name, category_id, region, summary, description, history, latitude, longitude, coords_verified, difficulty, visit_duration, season, access_info, safety_info, status, is_featured, sources) VALUES ('chorro-rio-venao', 'Chorro Río Venao', (SELECT id FROM destination_categories WHERE key='rios'), 'Valle de Arenal · Chepigana', 'Chorro escondido pero muy cercano: ideal para un domingo de chill.', 'Un chorro de agua que cae sobre una poza oscura entre paredes de roca. Divertido, relajante y fácil de combinar con Cascada Arenal en el mismo recorrido.', NULL, 8.628, -78.226, false, 'facil', 'Medio día', 'Verano (dic–abr) para agua más clara', 'Cercano a Arenal, caminata corta por el río.', 'Profundidad variable en la poza. Evitar después de lluvias fuertes.', 'published', false, ARRAY['https://www.instagram.com/p/DPovSRODfHd/','https://www.instagram.com/p/DfgX-g1Dq5f/']::text[]) ON CONFLICT (slug) DO NOTHING;
