INSERT INTO destinations (slug, name, category_id, region, summary, description, history, latitude, longitude, coords_verified, difficulty, visit_duration, season, access_info, safety_info, status, is_featured, sources) VALUES ('parque-nacional-darien', 'Parque Nacional Darién', (SELECT id FROM destination_categories WHERE key='selva'), 'Pinogana · acceso por El Real de Santa María', 'Patrimonio de la Humanidad (1981) y Reserva de la Biosfera: la selva más extensa de Centroamérica.', 'El parque nacional más grande de Panamá y el área protegida más grande de Centroamérica y el Caribe. Selva primaria, ríos, aves y fauna en uno de los lugares con mayor biodiversidad del continente.', 'Declarado Patrimonio de la Humanidad en 1981 y Reserva de la Biosfera por la UNESCO.', 8.017, -77.733, false, 'exigente', '2–4 días', 'Verano (dic–abr) recomendado', 'Panamericana hasta Yaviza, bote a El Real y traslado a la estación del parque. Requiere permiso de MiAmbiente.', 'Zona fronteriza: viajar solo con operador autorizado y permisos vigentes. Registrarse con SENAFRONT/MiAmbiente.', 'published', true, ARRAY['https://www.instagram.com/p/Dfk_rYaGOA2/','https://www.instagram.com/p/DfiYvP4hpeX/','https://www.instagram.com/p/CbBBvsmuFF_/','https://www.instagram.com/p/CbYdLx0F7_L/']::text[]) ON CONFLICT (slug) DO NOTHING;
