INSERT INTO destinations (slug, name, category_id, region, summary, description, history, latitude, longitude, coords_verified, difficulty, visit_duration, season, access_info, safety_info, status, is_featured, sources) VALUES ('el-real-de-santa-maria', 'El Real de Santa María', (SELECT id FROM destination_categories WHERE key='cultura'), 'Pinogana', 'Pueblo histórico a orillas del Tuira, puerta al Parque Nacional Darién.', 'Pueblo ribereño donde se observan pequeños restos históricos de la época colonial. Punto de partida hacia la estación del Parque Nacional Darién.', 'La región fue escenario de los primeros asentamientos españoles en tierra firme; Santa María la Antigua del Darién se fundó en 1510.', 8.131, -77.721, false, 'facil', 'Medio día', 'Todo el año', 'Bote desde Yaviza por el río Tuira.', 'Viajar con operador autorizado. Llevar documento de identidad.', 'published', false, ARRAY['https://www.instagram.com/p/Dfk_rYaGOA2/']::text[]) ON CONFLICT (slug) DO NOTHING;
