INSERT INTO destinations (slug, name, category_id, region, summary, description, history, latitude, longitude, coords_verified, difficulty, visit_duration, season, access_info, safety_info, status, is_featured, sources) VALUES ('yaviza', 'Yaviza', (SELECT id FROM destination_categories WHERE key='cultura'), 'Pinogana', 'Fin de la carretera Panamericana: el Tapón del Darién empieza aquí.', 'Kilómetro 12 580 desde Alaska. Pueblo sobre el río Chucunaque con las ruinas de la casa-fuerte colonial y vida fluvial intensa.', 'Conserva los restos de la casa-fuerte de Yaviza, construida para defender el paso fluvial.', 8.1557, -77.6926, true, 'facil', '2–3 horas', 'Todo el año', 'Por la Panamericana (≈ 6 h desde Ciudad de Panamá).', 'Puesto de control fronterizo: llevar identificación. No avanzar más allá sin operador.', 'published', true, ARRAY['https://www.instagram.com/p/CWtvo9_v4IK/']::text[]) ON CONFLICT (slug) DO NOTHING;
